        need_calls,need_text=req[name]
        miss_calls=sorted(need_calls-calls)
        miss_text=sorted(x for x in need_text if x not in seg)
        print(f"TEST_BEHAVIOR:{name}:CALLS="+",".join(sorted(calls)))
        if miss_calls or miss_text:
            errors.append(f"TEST_BEHAVIOR:{name}:missing_calls={miss_calls}:missing_text={miss_text}")
            print(f"TEST_BEHAVIOR_FAIL:{name}:missing_calls={miss_calls}:missing_text={miss_text}")
        else:
            print(f"TEST_BEHAVIOR_OK:{name}")

broker_path="phoenix_core/rakuten_rss_broker.py"
broker=sources.get(broker_path,Path(broker_path).read_text(encoding="utf-8"))
patterns={
 "ORDER_IDEMPOTENCY_KEY":r"client_order_id",
 "FILL_REPLAY_KEY":r"fill_event_id",
 "FILL_REPLAY_LEDGER":r"applied_fill_events",
 "SEND_ATTEMPT_STATE":r"SUBMIT_ATTEMPTED",
 "RECONCILE_PENDING_STATE":r"RECONCILE_PENDING",
 "UNPROVEN_FILL_FAIL_CLOSED":r"FILL_EVENT_ID_NOT_PROVEN",
}
for label,pat in patterns.items():
    matches=[]
    for i,line in enumerate(broker.splitlines(),1):
        if re.search(pat,line):
            matches.append((i,line.strip()))
    if not matches:
        errors.append("IDENTITY_MISSING:"+label)
        print("IDENTITY_MISSING:"+label)
    else:
        print("IDENTITY_EVIDENCE:"+label)
        for i,line in matches[:12]:
            print(f"  {broker_path}:{i}:{line}")

payload_matches=[]
for i,line in enumerate(broker.splitlines(),1):
    low=line.lower()
    if "payload" in low and ("sha" in low or "hash" in low):
        payload_matches.append((i,line.strip()))
if not payload_matches:
    errors.append("IDENTITY_MISSING:ECONOMIC_PAYLOAD_LOCK")
    print("IDENTITY_MISSING:ECONOMIC_PAYLOAD_LOCK")
else:
    print("IDENTITY_EVIDENCE:ECONOMIC_PAYLOAD_LOCK")
    for i,line in payload_matches[:12]:
        print(f"  {broker_path}:{i}:{line}")

# No speculative cumulative production-fill path in this repair.
for marker in ["def _apply_cumulative_fill", 'accounting_mode = "CUMULATIVE"', '"accounting_mode": "CUMULATIVE"']:
    if marker in broker:
        errors.append("SPECULATIVE_CUMULATIVE_PATH_PRESENT:"+marker)
        print("SPECULATIVE_CUMULATIVE_PATH_PRESENT:"+marker)

# Rakuten BUY quote source must be explicit and ticker-bound in production transport.
transport_path="phoenix_core/production_rakuten_rss_transport.py"
transport=sources.get(transport_path,Path(transport_path).read_text(encoding="utf-8"))
if "最良売気配値" not in transport:
    errors.append("QUOTE_SOURCE_MISSING:最良売気配値")
    print("QUOTE_SOURCE_MISSING:最良売気配値")
else:
    print("QUOTE_SOURCE_OK:最良売気配値")
if "read_executable_buy_price" not in transport or "ticker" not in transport:
    errors.append("QUOTE_TICKER_BINDING_NOT_PROVEN")
    print("QUOTE_TICKER_BINDING_NOT_PROVEN")
else:
    print("QUOTE_TICKER_BINDING_SOURCE_PRESENT")

# LIVE adapter may translate an accepted decision only; it must not evaluate strategy.
runtime_path="phoenix_core/strategy_execution_runtime.py"
runtime=sources.get(runtime_path,Path(runtime_path).read_text(encoding="utf-8"))
rtree=ast.parse(runtime,filename=runtime_path)
live_cls=next((n for n in rtree.body if isinstance(n,ast.ClassDef) and n.name=="RakutenLiveStrategyExecutionAdapter"),None)
if live_cls is None:
    errors.append("LIVE_ADAPTER_MISSING")
    print("LIVE_ADAPTER_MISSING")
else:
    submit=next((n for n in live_cls.body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) and n.name=="submit_entry"),None)
    if submit is None:
        errors.append("LIVE_SUBMIT_ENTRY_MISSING")
        print("LIVE_SUBMIT_ENTRY_MISSING")
    else:
        calls=[]
        for n in ast.walk(submit):
            if isinstance(n,ast.Call):
                f=n.func
                if isinstance(f,ast.Attribute): calls.append(f.attr)
                elif isinstance(f,ast.Name): calls.append(f.id)
        print("LIVE_SUBMIT_ENTRY_CALLS="+",".join(calls))
        if "evaluate_d1_entry" in calls:
            errors.append("LIVE_ADAPTER_DUPLICATES_STRATEGY_EVALUATION")
            print("LIVE_ADAPTER_DUPLICATES_STRATEGY_EVALUATION")
        if calls.count("submit_order") != 1:
            errors.append("LIVE_ADAPTER_SUBMIT_ORDER_COUNT="+str(calls.count("submit_order")))
            print("LIVE_ADAPTER_SUBMIT_ORDER_COUNT="+str(calls.count("submit_order")))
        else:
            print("LIVE_ADAPTER_SINGLE_BROKER_SUBMIT:PASS")

print("STATIC_VALIDATION_RESULT="+("FAIL" if errors else "PASS"))
print("RETURN_CODE="+("2" if errors else "0"))
if errors:
    print("STATIC_ERRORS="+";".join(errors))
    raise SystemExit(2)
